//! Declared-neutral linear RGB sample evidence. Not an illuminant estimator.
use crate::effects::Frame;use serde_json::{json,Value};
pub fn sample(f:&Frame,gamut:usize,region:[f64;4],trim:f64)->Result<Value,String>{
 if gamut>7||f.w==0||f.h==0||f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len())||region.iter().any(|v|!v.is_finite())||region[0]<0.||region[1]<0.||region[2]<=0.||region[3]<=0.||region[0]+region[2]>1.0000001||region[1]+region[3]>1.0000001||!(0. ..=0.4).contains(&trim){return Err("invalid neutral sample region/domain".into())}
 let x0=(region[0]*f.w as f64).floor() as usize;let y0=(region[1]*f.h as f64).floor() as usize;let x1=((region[0]+region[2])*f.w as f64).ceil().min(f.w as f64) as usize;let y1=((region[1]+region[3])*f.h as f64).ceil().min(f.h as f64) as usize;let pixels=(x1-x0).checked_mul(y1-y0).ok_or("neutral sample size overflow")?;crate::guard::reserve(pixels.checked_mul(24).ok_or("neutral sample allocation overflow")?);let mut channels:[Vec<f64>;3]=std::array::from_fn(|_|Vec::with_capacity(pixels));let mut excluded=0;
 for y in y0..y1{crate::guard::check();for x in x0..x1{let p=&f.d[(y*f.w+x)*4..(y*f.w+x+1)*4];if p.iter().any(|v|!v.is_finite())||p[3]<=0.||p[3]>1.||p[..3].iter().any(|v|*v<=1e-8){excluded+=1;continue}for j in 0..3{channels[j].push(p[j] as f64)}}}
 let n=channels[0].len();if n<4{return Err("neutral sample needs at least4positive visible pixels".into())}let cut=(n as f64*trim).floor() as usize;let mut mean=[0.;3];for j in 0..3{channels[j].sort_unstable_by(f64::total_cmp);mean[j]=channels[j][cut..n-cut].iter().sum::<f64>()/(n-2*cut) as f64;}
 let weights=super::managed::luma_weights(gamut);let y=(0..3).map(|j|weights[j]*mean[j]).sum::<f64>();if y<=1e-8{return Err("neutral sample nonpositive luminance".into())}let gains=mean.map(|v|y/v);if gains.iter().any(|v|!v.is_finite()||*v>100.){return Err("neutral correction exceeds gain100; choose a better sample".into())}
 Ok(json!({"region":region,"working_gamut":gamut,"positive_visible_pixels":n,"excluded_pixels":excluded,"trim_fraction_each_tail":trim,"trimmed_mean_rgb":mean,"target_neutral_linear":y,"suggested_gain_rgb":gains,"note":"User declares this patch neutral. Channelwise trimmed mean excludes nonpositive RGB/invalid/transparent pixels. Diagonal gains neutralize that statistic and preserve its luminance, not physical illuminant/Bradford adaptation or all-scene color accuracy. No effect applied."}))
}
